public class Main {
    public static void main(String[] args) {
        String item = "Wireless Headphones";
        int quantity = 2;
        double unitPrice = 1499.0;
        final double TAX = 0.18;
        double subtotal = quantity * unitPrice;
        double tax = subtotal * TAX;
        double total = subtotal + tax;
        System.out.println("Item: " + item + " x " + quantity);
        System.out.println("Subtotal: Rs " + subtotal + " | Tax: Rs " + tax + " | Total: Rs " + total);
    }
}

